# -*- coding: utf-8 -*-
"""Tạo Q&A từ bệnh phổ biến tại Việt Nam - đa dạng loại câu hỏi."""
import json

DISCLAIMER = "\n\n⚠️ Lưu ý: Đây là gợi ý sơ bộ, không thay thế khám bác sĩ."

DISEASES = [
  {"name":"Sốt xuất huyết Dengue","nguyen_nhan":"Virus Dengue lây qua muỗi vằn Aedes aegypti đốt. Muỗi hoạt động mạnh vào sáng sớm và chiều tối, sinh sản ở nước đọng.","trieu_chung":"Sốt cao đột ngột 39-40°C, đau đầu dữ dội, đau sau hốc mắt, đau cơ khớp, phát ban, xuất huyết dưới da (chấm đỏ li ti), chảy máu chân răng, chảy máu mũi. Trường hợp nặng: sốc dengue, tràn dịch, xuất huyết nội tạng.","dieu_tri":"Không có thuốc đặc trị. Hạ sốt bằng Paracetamol (KHÔNG dùng Aspirin hoặc Ibuprofen vì tăng nguy cơ xuất huyết), bù nước bằng oresol, nước dừa. Theo dõi tiểu cầu và hematocrit. Nhập viện nếu có dấu hiệu cảnh báo: đau bụng, nôn nhiều, li bì.","phong_ngua":"Diệt muỗi, lăng quăng. Đậy kín dụng cụ chứa nước. Ngủ mùng kể cả ban ngày. Phun thuốc diệt muỗi định kỳ. Mặc quần áo dài tay.","nguy_co":"Sống ở vùng dịch lưu hành (TP.HCM, đồng bằng sông Cửu Long, miền Trung). Mùa mưa tháng 6-11. Trẻ em. Người chưa từng nhiễm.","chan_doan":"Xét nghiệm NS1 Ag (ngày 1-5), xét nghiệm kháng thể IgM/IgG (sau ngày 5), công thức máu (tiểu cầu giảm, hematocrit tăng).","tien_luong":"Đa số tự khỏi sau 7-10 ngày. Tỷ lệ tử vong < 1% nếu điều trị đúng. Sốc dengue có tỷ lệ tử vong cao nếu không xử trí kịp thời."},
  {"name":"Tay chân miệng","nguyen_nhan":"Virus Enterovirus (chủ yếu EV71 và Coxsackie A16) lây qua đường tiêu hóa, tiếp xúc dịch mũi họng, phân, dịch bọng nước của người bệnh.","trieu_chung":"Sốt nhẹ đến cao, loét miệng (vết loét đỏ ở lưỡi, nướu, bên trong má), phát ban dạng bọng nước ở lòng bàn tay, lòng bàn chân, mông. Trẻ biếng ăn, quấy khóc. Biến chứng nặng: viêm não, viêm cơ tim.","dieu_tri":"Hạ sốt Paracetamol, giảm đau miệng bằng gel bôi, cho ăn thức ăn mềm nguội, bù nước. Theo dõi dấu hiệu nặng: giật mình, run chi, thở nhanh, nôn nhiều → nhập viện ngay.","phong_ngua":"Rửa tay thường xuyên bằng xà phòng. Vệ sinh đồ chơi, sàn nhà. Không cho trẻ bệnh đến trường. Cách ly trẻ bệnh 10 ngày.","nguy_co":"Trẻ em dưới 5 tuổi (đặc biệt dưới 3 tuổi). Nhà trẻ, mẫu giáo. Mùa hè-thu. Vùng đông dân cư.","chan_doan":"Chủ yếu dựa vào lâm sàng (sốt + loét miệng + ban tay chân). Xét nghiệm RT-PCR dịch họng hoặc phân.","tien_luong":"Đa số tự khỏi trong 7-10 ngày. EV71 có nguy cơ biến chứng thần kinh cao. Tử vong hiếm nếu phát hiện sớm."},
  {"name":"Viêm gan B","nguyen_nhan":"Virus HBV lây qua đường máu, quan hệ tình dục không an toàn, mẹ truyền sang con khi sinh. Việt Nam là vùng dịch lưu hành cao (~8% dân số nhiễm HBV).","trieu_chung":"Giai đoạn cấp: mệt mỏi, chán ăn, buồn nôn, đau hạ sườn phải, vàng da vàng mắt. Giai đoạn mạn: nhiều người không triệu chứng trong nhiều năm.","dieu_tri":"Viêm gan B mạn: thuốc kháng virus Tenofovir hoặc Entecavir theo phác đồ Bộ Y tế khi đủ chỉ định (HBV DNA > 2000 IU/mL + men gan tăng hoặc xơ hóa). Theo dõi định kỳ 3-6 tháng/lần.","phong_ngua":"Tiêm vaccine viêm gan B (3 mũi: 0-1-6 tháng). Tiêm cho trẻ sơ sinh trong 24h đầu. Quan hệ tình dục an toàn. Không dùng chung kim tiêm.","nguy_co":"Nhân viên y tế. Con của mẹ nhiễm HBV. Người tiêm chích ma túy. Quan hệ tình dục không an toàn.","chan_doan":"HBsAg, Anti-HBs, HBeAg, HBV DNA định lượng, men gan ALT/AST, siêu âm gan, FibroScan đánh giá xơ hóa.","tien_luong":"90% người lớn nhiễm cấp sẽ tự khỏi. 90% trẻ sơ sinh nhiễm sẽ chuyển mạn. Viêm gan B mạn có nguy cơ xơ gan và ung thư gan."},
  {"name":"Lao phổi","nguyen_nhan":"Vi khuẩn Mycobacterium tuberculosis lây qua đường hô hấp. Việt Nam đứng thứ 11 trên toàn cầu về gánh nặng lao.","trieu_chung":"Ho kéo dài trên 2 tuần, ho ra máu, sốt nhẹ về chiều, ra mồ hôi đêm, gầy sút cân, mệt mỏi, đau ngực, khó thở.","dieu_tri":"Phác đồ 2RHZE/4RH (Bộ Y tế): 2 tháng tấn công (Rifampicin + Isoniazid + Pyrazinamide + Ethambutol), 4 tháng duy trì. Uống thuốc đều đặn, KHÔNG bỏ thuốc giữa chừng.","phong_ngua":"Tiêm vaccine BCG cho trẻ sơ sinh. Thông thoáng nhà cửa. Đeo khẩu trang. Dinh dưỡng tốt tăng sức đề kháng.","nguy_co":"Người tiếp xúc gần bệnh nhân lao. HIV/AIDS. Suy dinh dưỡng. Đái tháo đường. Người ở nơi đông đúc.","chan_doan":"X-quang phổi, nhuộm soi đờm AFB, GeneXpert MTB/RIF (kết quả 2 giờ, phát hiện lao kháng thuốc), nuôi cấy đờm.","tien_luong":"Tỷ lệ khỏi > 90% nếu điều trị đúng phác đồ. Lao kháng thuốc MDR-TB khó điều trị hơn."},
  {"name":"Đái tháo đường type 2","nguyen_nhan":"Kháng insulin kết hợp suy giảm chức năng tế bào beta tụy. Yếu tố: béo phì, ít vận động, di truyền, tuổi > 45.","trieu_chung":"Khát nước nhiều, tiểu nhiều, đói nhiều, sụt cân không rõ nguyên nhân, mệt mỏi, mờ mắt, vết thương lâu lành, tê bì chân tay. Nhiều người không có triệu chứng rõ.","dieu_tri":"Thay đổi lối sống + Metformin (bước 1), thêm Sulfonylurea hoặc DPP-4 inhibitor hoặc SGLT2 inhibitor hoặc Insulin khi cần. Mục tiêu HbA1c < 7%.","phong_ngua":"Duy trì cân nặng hợp lý BMI 18.5-23. Tập thể dục 150 phút/tuần. Hạn chế đường, thức ăn nhanh. Khám định kỳ đo đường huyết.","nguy_co":"Béo phì BMI ≥ 25. Tiền sử gia đình. Tuổi > 45. Rối loạn mỡ máu. Tăng huyết áp. Tiền sử đái tháo đường thai kỳ.","chan_doan":"Đường huyết đói ≥ 126 mg/dL. HbA1c ≥ 6.5%. Nghiệm pháp dung nạp glucose OGTT ≥ 200 mg/dL sau 2 giờ.","tien_luong":"Bệnh mạn tính suốt đời nhưng kiểm soát tốt thì sống bình thường. Biến chứng: bệnh thận, mù mắt, đoạn chi, đột quỵ."},
  {"name":"Tăng huyết áp","nguyen_nhan":"Đa số nguyên phát (90-95%) không rõ nguyên nhân. Yếu tố: ăn mặn, béo phì, ít vận động, stress, di truyền, hút thuốc, rượu bia.","trieu_chung":"Phần lớn không triệu chứng (kẻ giết người thầm lặng). Khi rất cao: đau đầu, chóng mặt, nhìn mờ, ù tai. Biến chứng: đột quỵ, nhồi máu cơ tim, suy tim, suy thận.","dieu_tri":"Giảm muối < 5g/ngày, tập thể dục 30 phút/ngày, giảm cân, bỏ thuốc lá. Thuốc: ức chế men chuyển, chẹn thụ thể AT1, chẹn kênh calci, lợi tiểu. Mục tiêu < 140/90 mmHg.","phong_ngua":"Ăn nhạt. Tập thể dục đều đặn. Duy trì cân nặng hợp lý. Không hút thuốc. Kiểm tra huyết áp định kỳ.","nguy_co":"Tuổi > 40. Tiền sử gia đình. Béo phì. Ăn mặn. Ít vận động. Hút thuốc lá. Stress kéo dài.","chan_doan":"Đo huyết áp nhiều lần ≥ 140/90 mmHg. Holter huyết áp 24 giờ. Xét nghiệm đánh giá tổn thương cơ quan đích.","tien_luong":"Kiểm soát tốt thì sống bình thường. Không điều trị: nguy cơ đột quỵ tăng 7 lần, nhồi máu cơ tim tăng 3 lần."},
  {"name":"Viêm dạ dày - H. pylori","nguyen_nhan":"Vi khuẩn Helicobacter pylori lây qua đường miệng-miệng, phân-miệng. Tỷ lệ nhiễm H. pylori tại Việt Nam rất cao ~70% dân số.","trieu_chung":"Đau thượng vị, nóng rát, đầy bụng, ợ hơi ợ chua, buồn nôn, chán ăn. Biến chứng: loét dạ dày tá tràng, xuất huyết tiêu hóa, ung thư dạ dày.","dieu_tri":"Phác đồ diệt H. pylori: PPI (Omeprazole) + Amoxicillin + Clarithromycin 14 ngày. Hoặc bộ bốn có Bismuth. Kiểm tra diệt sạch sau 4 tuần ngưng thuốc.","phong_ngua":"Ăn chín uống sôi. Rửa tay trước khi ăn. Không dùng chung bát đũa. Hạn chế rượu bia, thức ăn cay nóng.","nguy_co":"Sống vùng đông dân, vệ sinh kém. Dùng chung dụng cụ ăn uống. Người thân có H. pylori.","chan_doan":"Test hơi thở C13/C14. Nội soi dạ dày + test urease nhanh CLO test. Xét nghiệm phân tìm kháng nguyên H. pylori.","tien_luong":"Tỷ lệ diệt H. pylori 85-90% với phác đồ đúng. Loét dạ dày lành sau 4-8 tuần điều trị."},
  {"name":"Viêm phổi cộng đồng","nguyen_nhan":"Vi khuẩn (Streptococcus pneumoniae phổ biến nhất), virus (cúm, SARS-CoV-2, RSV). Lây qua đường hô hấp.","trieu_chung":"Sốt cao, rét run, ho có đờm vàng xanh, đau ngực khi thở sâu, khó thở, thở nhanh. Người già có thể lú lẫn, không sốt. Trẻ em: thở nhanh, co rút lồng ngực.","dieu_tri":"Kháng sinh: nhẹ uống Amoxicillin hoặc Azithromycin, nặng Ceftriaxone + Azithromycin tiêm. Hạ sốt, bù nước, thở oxy nếu SpO2 < 94%.","phong_ngua":"Tiêm vaccine phế cầu, vaccine cúm hàng năm. Rửa tay thường xuyên. Không hút thuốc.","nguy_co":"Người > 65 tuổi. Trẻ em < 5 tuổi. COPD. Đái tháo đường. Suy tim. HIV/AIDS. Hút thuốc.","chan_doan":"X-quang phổi (đám mờ phế nang). Công thức máu, CRP, Procalcitonin. Cấy đờm. SpO2.","tien_luong":"Đa số khỏi sau 1-2 tuần. Tử vong ~1% ngoại trú, 5-15% nhập viện."},
  {"name":"Sốt rét","nguyen_nhan":"Ký sinh trùng Plasmodium (P. falciparum, P. vivax) lây qua muỗi Anopheles đốt. Phổ biến ở Tây Nguyên, miền Trung, Tây Bắc.","trieu_chung":"Cơn sốt rét: rét run 15-60 phút → sốt cao 40-41°C 2-6 giờ → vã mồ hôi hạ sốt. Sốt rét ác tính: co giật, hôn mê, suy thận, thiếu máu nặng.","dieu_tri":"P. falciparum: DHA-PPQ 3 ngày. P. vivax: Chloroquine 3 ngày + Primaquine 14 ngày. Sốt rét ác tính: Artesunate tiêm tĩnh mạch.","phong_ngua":"Ngủ màn tẩm hóa chất. Phun thuốc diệt muỗi. Mặc quần áo dài tay khi vào rừng. Uống thuốc dự phòng khi đến vùng dịch.","nguy_co":"Người sống/làm việc ở vùng rừng núi, biên giới. Quân nhân, công nhân cao su. Phụ nữ mang thai. Trẻ em.","chan_doan":"Lam máu ngoại vi tìm ký sinh trùng. Test nhanh RDT. PCR cho trường hợp khó.","tien_luong":"P. vivax tiên lượng tốt nhưng hay tái phát. P. falciparum nguy hiểm hơn, sốt rét ác tính tử vong 10-20%."},
  {"name":"Bệnh Gout","nguyen_nhan":"Acid uric máu tăng cao, lắng đọng tinh thể urat tại khớp. Do ăn nhiều purine (nội tạng, hải sản, bia rượu), giảm đào thải acid uric qua thận.","trieu_chung":"Cơn gout cấp: sưng nóng đỏ đau dữ dội đột ngột ở khớp ngón chân cái, thường ban đêm. Gout mạn: hạt tophi, biến dạng khớp.","dieu_tri":"Cơn cấp: Colchicine, NSAIDs (Indomethacin), Corticosteroid. Dự phòng: Allopurinol hoặc Febuxostat hạ acid uric mục tiêu < 360 µmol/L. Uống nước > 2L/ngày.","phong_ngua":"Hạn chế bia rượu đặc biệt bia. Giảm thực phẩm giàu purine. Uống nhiều nước. Duy trì cân nặng hợp lý.","nguy_co":"Nam giới > 40 tuổi. Béo phì. Uống nhiều bia rượu. Ăn nhiều nội tạng, hải sản. Suy thận. Dùng thuốc lợi tiểu.","chan_doan":"Acid uric máu > 420 µmol/L (nam). Chọc dịch khớp tìm tinh thể urat. X-quang khớp. Siêu âm khớp.","tien_luong":"Kiểm soát tốt nếu duy trì acid uric thấp. Không điều trị: cơn gout tái phát, tổn thương khớp vĩnh viễn, sỏi thận."},
  {"name":"Thiếu máu thiếu sắt","nguyen_nhan":"Chế độ ăn thiếu sắt, mất máu mạn tính (kinh nguyệt nhiều, xuất huyết tiêu hóa, giun móc), nhu cầu sắt tăng (mang thai, trẻ đang lớn). Rất phổ biến ở phụ nữ và trẻ em VN.","trieu_chung":"Mệt mỏi, xanh xao, chóng mặt, hoa mắt, nhịp tim nhanh, khó thở khi gắng sức, móng tay giòn lõm, tóc rụng, lưỡi nhợt.","dieu_tri":"Bổ sung sắt Ferrous sulfate 300mg x 2-3 lần/ngày uống lúc đói với nước cam. Tránh uống cùng trà, sữa, canxi. Điều trị 3-6 tháng. Tìm nguyên nhân mất máu.","phong_ngua":"Ăn thực phẩm giàu sắt: thịt đỏ, gan, huyết, rau xanh đậm. Bổ sung sắt cho thai phụ. Tẩy giun định kỳ 6 tháng/lần.","nguy_co":"Phụ nữ kinh nguyệt nhiều. Thai phụ. Trẻ ăn dặm thiếu. Người ăn chay. Nhiễm giun móc.","chan_doan":"Huyết đồ: Hb giảm (nam < 13g/dL, nữ < 12g/dL), MCV giảm, ferritin giảm < 30 ng/mL, sắt huyết thanh giảm.","tien_luong":"Đáp ứng tốt với điều trị sắt. Hb tăng sau 2-4 tuần. Cần uống đủ 3-6 tháng để bù đầy kho sắt."},
  {"name":"Đột quỵ não","nguyen_nhan":"Đột quỵ thiếu máu (80%): cục máu đông tắc mạch não. Đột quỵ xuất huyết (20%): vỡ mạch máu não. Nguyên nhân chính: tăng huyết áp, xơ vữa động mạch, rung nhĩ.","trieu_chung":"Đột ngột: yếu liệt nửa người, méo miệng, nói khó, nhìn mờ một bên, đau đầu dữ dội. Quy tắc FAST: Face mặt méo, Arm tay yếu, Speech nói khó, Time gọi cấp cứu ngay.","dieu_tri":"CẤP CỨU gọi 115 ngay. Đột quỵ thiếu máu: tiêu sợi huyết rtPA trong 4.5 giờ đầu (giờ vàng), lấy huyết khối trong 6-24 giờ. Xuất huyết: kiểm soát huyết áp, phẫu thuật nếu cần.","phong_ngua":"Kiểm soát huyết áp < 140/90. Kiểm soát đường huyết. Bỏ thuốc lá. Điều trị rung nhĩ. Tập thể dục đều đặn.","nguy_co":"Tăng huyết áp (nguy cơ số 1). Tuổi > 55. Đái tháo đường. Rung nhĩ. Hút thuốc. Rối loạn mỡ máu.","chan_doan":"CT scan não không cản quang (phân biệt xuất huyết vs thiếu máu). MRI não. CT mạch máu não. Điện tâm đồ.","tien_luong":"Phụ thuộc vào loại đột quỵ và thời gian cấp cứu. 1/3 phục hồi tốt, 1/3 tàn phế, 1/3 tử vong."},
  {"name":"Thoái hóa khớp gối","nguyen_nhan":"Lão hóa sụn khớp theo tuổi. Yếu tố: béo phì, chấn thương khớp trước đó, nghề nghiệp đứng lâu khuân vác.","trieu_chung":"Đau khớp gối tăng khi đi lại, lên xuống cầu thang, ngồi xổm. Cứng khớp buổi sáng < 30 phút. Khớp kêu lạo xạo. Sưng khớp. Biến dạng giai đoạn muộn.","dieu_tri":"Giảm cân. Vật lý trị liệu, tập cơ tứ đầu đùi. Paracetamol, NSAIDs ngắn ngày, Glucosamine sulfate. Tiêm khớp Hyaluronic acid. Phẫu thuật thay khớp khi nặng.","phong_ngua":"Duy trì cân nặng hợp lý. Tập thể dục nhẹ nhàng (đi bộ, bơi, đạp xe). Tránh ngồi xổm, quỳ gối. Bổ sung calcium, vitamin D.","nguy_co":"Tuổi > 50. Nữ giới sau mãn kinh. Béo phì. Chấn thương khớp gối trước đó. Nghề khuân vác nặng.","chan_doan":"X-quang khớp gối (hẹp khe khớp, gai xương). Xét nghiệm máu bình thường phân biệt với viêm khớp dạng thấp.","tien_luong":"Bệnh tiến triển chậm, không đảo ngược. Điều trị sớm giúp duy trì chức năng khớp và giảm đau."},
  {"name":"Viêm mũi dị ứng","nguyen_nhan":"Phản ứng dị ứng với bụi nhà, mạt bụi, phấn hoa, lông thú, nấm mốc. Rất phổ biến tại Việt Nam do khí hậu nóng ẩm.","trieu_chung":"Hắt hơi liên tục, ngứa mũi, chảy nước mũi trong, nghẹt mũi, ngứa mắt chảy nước mắt. Hay tái phát theo mùa hoặc quanh năm.","dieu_tri":"Tránh dị nguyên. Kháng histamine (Cetirizine, Loratadine), corticosteroid xịt mũi (Fluticasone), nước muối rửa mũi. Liệu pháp miễn dịch đặc hiệu cho trường hợp nặng.","phong_ngua":"Giặt ga gối nước nóng hàng tuần. Hút bụi thường xuyên. Không nuôi thú cưng trong phòng ngủ. Dùng máy lọc không khí.","nguy_co":"Tiền sử gia đình dị ứng. Tiếp xúc nhiều bụi mạt bụi. Sống nơi ô nhiễm. Trẻ có cơ địa atopy.","chan_doan":"Lâm sàng + tiền sử. Test lẩy da skin prick test. IgE đặc hiệu. Nội soi mũi thấy niêm mạc phù nề nhợt.","tien_luong":"Bệnh mạn tính nhưng kiểm soát tốt bằng thuốc. Không điều trị có thể dẫn đến viêm xoang, hen suyễn."},
  {"name":"Cúm mùa","nguyen_nhan":"Virus cúm A (H1N1, H3N2), cúm B lây qua giọt bắn khi ho, hắt hơi. Dịch thường xảy ra mùa đông-xuân ở miền Bắc, quanh năm ở miền Nam.","trieu_chung":"Sốt cao đột ngột 38-40°C, rét run, đau đầu, đau cơ toàn thân, mệt mỏi nhiều, ho khan, đau họng. Phân biệt với cảm lạnh: cúm nặng hơn, sốt cao hơn.","dieu_tri":"Đa số tự khỏi sau 5-7 ngày. Hạ sốt Paracetamol, uống nhiều nước, nghỉ ngơi. Oseltamivir (Tamiflu) trong 48 giờ đầu cho nhóm nguy cơ cao.","phong_ngua":"Tiêm vaccine cúm hàng năm cho người > 65, trẻ em, thai phụ, bệnh mạn tính. Rửa tay, đeo khẩu trang.","nguy_co":"Trẻ < 5 tuổi. Người > 65. Thai phụ. Bệnh phổi, tim mạch, đái tháo đường, suy giảm miễn dịch.","chan_doan":"Test nhanh cúm. RT-PCR cúm. Lâm sàng trong mùa dịch.","tien_luong":"Tự khỏi ở người khỏe mạnh. Biến chứng viêm phổi ở nhóm nguy cơ."},
  {"name":"Giun sán đường ruột","nguyen_nhan":"Giun đũa, giun móc, giun kim, giun tóc lây qua ăn rau sống, uống nước không sạch, đi chân đất. Tỷ lệ nhiễm giun ở nông thôn VN còn cao.","trieu_chung":"Đau bụng quanh rốn, tiêu chảy, chán ăn, gầy yếu, thiếu máu, ngứa hậu môn (giun kim). Trẻ em: chậm phát triển, kém tập trung.","dieu_tri":"Tẩy giun Albendazole 400mg liều duy nhất hoặc Mebendazole 500mg liều duy nhất. Giun kim lặp lại sau 2 tuần. Điều trị thiếu máu kèm theo.","phong_ngua":"Tẩy giun định kỳ 6 tháng/lần cho cả gia đình. Rửa tay trước ăn, sau vệ sinh. Ăn chín uống sôi. Không đi chân đất.","nguy_co":"Trẻ em nông thôn. Người đi chân đất. Ăn rau sống không rửa sạch. Vùng dùng phân tươi bón rau.","chan_doan":"Xét nghiệm phân tìm trứng giun Kato-Katz. Soi phân trực tiếp. Máu: bạch cầu ái toan tăng.","tien_luong":"Tốt, điều trị đơn giản hiệu quả. Có thể tái nhiễm nếu không thay đổi thói quen."},
  {"name":"Thủy đậu","nguyen_nhan":"Virus Varicella-Zoster VZV lây rất mạnh qua đường hô hấp và tiếp xúc dịch bọng nước.","trieu_chung":"Sốt nhẹ, mệt mỏi, phát ban bọng nước trên nền da đỏ ngứa nhiều, ban mọc nhiều đợt, bắt đầu từ mặt thân rồi lan ra tay chân.","dieu_tri":"Trẻ khỏe mạnh: hạ sốt Paracetamol, chống ngứa kem calamine, cắt ngắn móng tay. Người lớn/suy giảm miễn dịch: Acyclovir 800mg x 5 lần/ngày x 7 ngày.","phong_ngua":"Tiêm vaccine thủy đậu 2 mũi. Cách ly người bệnh đến khi bọng nước đóng vảy.","nguy_co":"Trẻ chưa tiêm vaccine. Người lớn chưa mắc. Thai phụ (nguy hiểm cho thai). Suy giảm miễn dịch.","chan_doan":"Lâm sàng (ban bọng nước đặc trưng). PCR dịch bọng nước nếu cần.","tien_luong":"Tốt ở trẻ khỏe mạnh, khỏi trong 1-2 tuần. Người lớn nặng hơn. Biến chứng: viêm phổi, viêm não hiếm gặp."},
  {"name":"Viêm gan A","nguyen_nhan":"Virus HAV lây qua đường phân-miệng: thực phẩm/nước nhiễm, hải sản sống, rau sống không rửa sạch.","trieu_chung":"Mệt mỏi, chán ăn, buồn nôn, đau bụng vùng gan, sốt nhẹ, vàng da vàng mắt, nước tiểu sẫm, phân bạc màu.","dieu_tri":"Không có thuốc đặc trị. Nghỉ ngơi, ăn nhạt, kiêng rượu dầu mỡ. Không dùng Paracetamol liều cao. Theo dõi chức năng gan.","phong_ngua":"Tiêm vaccine viêm gan A. Ăn chín uống sôi. Rửa tay trước ăn và sau vệ sinh.","nguy_co":"Trẻ em vùng vệ sinh kém. Du lịch vùng dịch. Nhân viên nhà bếp. Chưa tiêm vaccine.","chan_doan":"Anti-HAV IgM (nhiễm cấp), Anti-HAV IgG (miễn dịch). Men gan ALT/AST tăng cao. Bilirubin tăng.","tien_luong":"Tự khỏi hoàn toàn trong 2-6 tháng, không chuyển mạn."},
]

QUESTION_TEMPLATES = {
    "nguyen_nhan": ["{name} do nguyên nhân gì?", "Nguyên nhân gây {name} là gì?", "Tại sao bị {name}?", "{name} bắt nguồn từ đâu?"],
    "trieu_chung": ["{name} có triệu chứng gì?", "Dấu hiệu nhận biết {name} là gì?", "Làm sao biết mình bị {name}?", "Biểu hiện của {name} như thế nào?"],
    "dieu_tri": ["{name} điều trị như thế nào?", "Cách chữa {name}?", "Phương pháp điều trị {name} hiện nay?", "Bị {name} thì uống thuốc gì?"],
    "phong_ngua": ["{name} phòng ngừa bằng cách nào?", "Làm sao để tránh bị {name}?", "Cách phòng tránh {name}?", "Biện pháp phòng ngừa {name} là gì?"],
    "nguy_co": ["Ai có nguy cơ bị {name}?", "Những ai dễ mắc {name}?", "Yếu tố nguy cơ của {name} là gì?", "{name} thường gặp ở đối tượng nào?"],
    "chan_doan": ["Chẩn đoán {name} bằng cách nào?", "Xét nghiệm gì để phát hiện {name}?", "Làm sao xác định bị {name}?"],
    "tien_luong": ["Tiên lượng {name} như thế nào?", "{name} có nguy hiểm không?", "{name} có chữa được không?", "Bị {name} có nghiêm trọng không?"],
}

import random
random.seed(42)
result = []

for disease in DISEASES:
    for qtype, templates in QUESTION_TEMPLATES.items():
        if qtype not in disease:
            continue
        q_template = random.choice(templates)
        q = q_template.format(name=disease["name"])
        a = disease[qtype] + DISCLAIMER
        result.append({"question": q, "answer": a, "source": "vn_medical_native"})

OUT = r"C:\NDT\PJ\MediSign_AI\data\training_raw\vn_diseases.json"
with open(OUT, "w", encoding="utf-8") as f:
    json.dump(result, f, ensure_ascii=False, indent=2)
print(f"Generated {len(result)} entries -> {OUT}")
